export type ProviderState = "available" | "exhausted" | "unknown";

export type UsageWindow = {
	name: string;
	usedPercent: number;
	resetAt?: number;
};

/** A usage-limit reset the account can still spend (Claude's "reset ticket"). */
export type ResetTicket = {
	id: string;
	label?: string;
	resetsLeft: number;
	expiresAt: number;
};

/** A spent or lapsed reset ticket; `at` is epoch seconds. */
export type TicketUse = {
	provider: string;
	grantId: string;
	at: number;
	result: "reset" | "already_used" | "ineligible" | "expired";
	source: "auto" | "manual";
	resetsLeft?: number;
};

export type Provider = {
	id: string;
	name: string;
	plan: string;
	price: string;
	monthlyUsd: number;
	state: ProviderState;
	metric?: string;
	/** `metric` as a number of cents, for charts that divide it. */
	balanceCents?: number;
	windows: UsageWindow[];
	/**
	 * Prepaid credit (a topped-up balance) rather than a vendor quota. The card
	 * reads its window as this month's share of the month's credit.
	 */
	prepaid?: boolean;
	tickets: ResetTicket[];
	/** Newest first. */
	ticketHistory: TicketUse[];
	renewsAt?: number;
	endsAt?: number;
	supported: boolean;
	checkedAt?: number;
};

export type DayUsage = { day: string; usedPercent: number };

export type WindowHistory = { days: DayUsage[]; beforeTracking: number };

export type DaySpend = { day: string; cents: number };

/** provider id -> dated dollar spend for a prepaid balance. */
export type ProviderSpend = Record<string, { days: DaySpend[] }>;

/** provider id -> window name -> daily usage in the current cycle. */
export type ProviderHistory = Record<string, Record<string, WindowHistory>>;

export type Board = {
	monthlyUsd: number;
	yearlyUsd: number;
	/** Already in the user's saved order; providers it does not name follow in catalog order. */
	providers: Provider[];
	/** The order the user saved by dragging card headers; empty until they (or the first Usage share seed) saved one. */
	order: string[];
	history?: ProviderHistory;
	spend?: ProviderSpend;
	/** The server spends a reset ticket on its own in its last five minutes. */
	autoReset: boolean;
	auth: {
		openai: boolean;
		commandcode: boolean;
		opencodeGo: boolean;
		grok: boolean;
		lithosai: boolean;
		openrouter: boolean;
		openrouterManagement: boolean;
		claude: boolean;
	};
};

