import { getJson } from "$lib/api/request.js";

export type UsageProvider = { id: string; name: string; tokens: number; requests: number };
export type UsageModel = {
	model: string;
	providerId: string;
	providerName: string;
	tokens: number;
	requests: number;
};
export type UsageShare = {
	days: number;
	totalTokens: number;
	totalRequests: number;
	providers: UsageProvider[];
	models: UsageModel[];
};

export function loadUsageShare(days: 7 | 30): Promise<UsageShare> {
	return getJson<UsageShare>(`/api/usage-share?days=${days}`);
}

export function formatTokens(value: number): string {
	if (value >= 1e9) return `${(value / 1e9).toFixed(1)}B`;
	if (value >= 1e6) return `${(value / 1e6).toFixed(1)}M`;
	if (value >= 1e3) return `${Math.round(value / 1e3)}K`;
	return String(value);
}

