content.text:
import { resetAtMs } from "./format.ts";

export function windowLabel(name: string): string {
	if (name === "weekly") return "Weekly";
	if (name === "monthly") return "Monthly";
	if (name === "5h" || name === "session" || name === "rolling") return "Session";
	return name;
}

/** `2026-09-29` -> `Sep 29 Mon` (local calendar, no timezone shift). */
export function formatDay(day: string): string {
	const [y, m, d] = day.split("-").map(Number);
	const date = new Date(y, (m ?? 1) - 1, d ?? 1);
	if (Number.isNaN(date.getTime())) return day;
	const md = date.toLocaleDateString("en-US", {
		month: "short",
		day: "numeric",
	});
	return `${md} ${date.toLocaleDateString("en-US", { weekday: "short" })}`;
}

/** `Oct 23` expiry; the card drops the date when the ticket has none. */
export function ticketExpiry(expiresAt: number, now = Date.now()): string {
	const ms = resetAtMs(expiresAt);
	if (ms == null || ms <= now) return "";
	const date = new Date(ms);
	if (Number.isNaN(date.getTime())) return "";
	const sameYear = date.getFullYear() === new Date(now).getFullYear();
	return date.toLocaleDateString("en-US", {
		month: "short",
		day: "numeric",
		...(!sameYear ? { year: "numeric" } : {}),
	});
}

/** When a ticket stops being spendable, or null for one without an expiry (i64::MAX) or one already gone. */
export function ticketExpiresMs(expiresAt: number, now = Date.now()): number | null {
	const ms = resetAtMs(expiresAt);
	if (ms == null || ms <= now || ms - now > 366 * DAY_MS) return null;
	return ms;
}

type TicketKind = { scope?: "all" | "model" | string; model?: string };

/** `Full` or the model a model reset is for (`Fable`). */
export function ticketKind(ticket: TicketKind): string {
	return ticket.scope === "model" ? (ticket.model ?? "Model") : "Full";
}

/** `Full reset`, `Fable reset`: the pill and dialog name, as claude.ai words it. */
export function ticketName(ticket: TicketKind): string {
	return `${ticketKind(ticket)} reset`;
}

/** What spending the ticket does, for its confirmation dialog. */
export function ticketEffect(ticket: TicketKind): string {
	if (ticket.scope !== "model") return "Clears your session and weekly usage now. This can't be undone.";
	const model = ticket.model ?? "this model's";
	return `Refills your session and ${model} allowance, and returns ${model} usage to your weekly limit. Other weekly usage stays. This can't be undone.`;
}

/** Tickets still spendable at `now`, soonest expiry first. */
export function liveTickets<T extends { expiresAt: number }>(tickets: readonly T[], now = Date.now()): T[] {
	return tickets
		.filter((ticket) => (resetAtMs(ticket.expiresAt) ?? Infinity) > now)
		.toSorted((a, b) => (resetAtMs(a.expiresAt) ?? Infinity) - (resetAtMs(b.expiresAt) ?? Infinity));
}

/**
 * The soonest live ticket that clears the weekly window. Only this one changes
 * the weekly pace: a model reset leaves the weekly usage in place.
 */
export function weeklyTicket<T extends { expiresAt: number } & TicketKind>(
	tickets: readonly T[],
	now = Date.now(),
): T | undefined {
	return liveTickets(tickets, now).find((ticket) => ticket.scope !== "model");
}

const TICKET_USE_VERBS: Record<string, string> = {
	reset: "Used",
	expired: "Expired unused",
	already_used: "Already used",
	ineligible: "Not eligible",
};

/** One ticket history row split for a table: verb, `Oct 23`, `00:55`, and `auto`/`manual` (none when it lapsed). */
export function ticketUseParts(use: { at: number; result: string; source: string } & TicketKind): {
	verb: string;
	kind: string;
	day: string;
	clock: string;
	source: string | null;
} {
	const date = new Date(resetAtMs(use.at) ?? 0);
	return {
		verb: TICKET_USE_VERBS[use.result] ?? use.result,
		kind: ticketKind(use),
		day: date.toLocaleDateString("en-US", { month: "short", day: "numeric" }),
		clock: date.toLocaleTimeString("en-GB", {
			hour: "2-digit",
			minute: "2-digit",
			hourCycle: "h23",
		}),
		source: use.result === "expired" ? null : use.source,
	};
}

/** One ticket history row: `Used Oct 23 00:55 · Fable reset · auto`. */
export function ticketUseLabel(use: { at: number; result: string; source: string } & TicketKind): string {
	const { verb, day, clock, source } = ticketUseParts(use);
	const head = `${verb} ${day} ${clock} · ${ticketName(use)}`;
	return source ? `${head} · ${source}` : head;
}

/**
 * `D-7` … `D-1` by calendar day inside the last week, `5h left` inside the last
 * 72 hours, `D-day` once it is gone, else "".
 */
export function ticketDday(expiresAt: number, now = Date.now()): string {
	const ms = resetAtMs(expiresAt) ?? now;
	const left = ms - now;
	if (left <= 0) return "D-day";
	if (left < 72 * 3_600_000) return `${Math.max(1, Math.ceil(left / 3_600_000))}h left`;
	// A midnight end belongs to the day before, as on the chart.
	const end = new Date(ms - 1);
	const today = new Date(now);
	const days = Math.round(
		(Date.UTC(end.getFullYear(), end.getMonth(), end.getDate()) -
			Date.UTC(today.getFullYear(), today.getMonth(), today.getDate())) /
			DAY_MS,
	);
	return days <= 7 ? `D-${days}` : "";
}

export type StripDay = {
	day: string;
	/** Used% that day; null when nothing was tracked or the day has not come yet. */
	pct: number | null;
	today: boolean;
	future: boolean;
	/** The day the window resets on. */
	reset: boolean;
};

const DAY_MS = 86_400_000;

export type SpendStripDay = {
	day: string;
	/** Cents spent that day; null for a day nothing was read (or a day yet to come). */
	cents: number | null;
	today: boolean;
	future: boolean;
};

/**
 * The calendar month of `now`, one slot per day, oldest first — the same basis
 * as a monthly quota window, but a prepaid balance has no reset to end the
 * month on, so the strip is the month itself.
 *
 * A day with no reading is an empty slot rather than a `$0.00`: the board only
 * knows the days it recorded.
 */
export function spendStrip(days: readonly { day: string; cents: number }[], now: number): SpendStripDay[] {
	const at = new Date(now);
	const today = dayKey(at);
	const spent = new Map(days.map((day) => [day.day, day.cents]));
	const lastDay = new Date(at.getFullYear(), at.getMonth() + 1, 0).getDate();
	const strip: SpendStripDay[] = [];
	for (let date = 1; date <= lastDay; date++) {
		const day = dayKey(new Date(at.getFullYear(), at.getMonth(), date));
		strip.push({
			day,
			cents: spent.get(day) ?? null,
			today: day === today,
			future: day > today,
		});
	}
	return strip;
}

