import { getJson, postJson } from "$lib/api/request.js";
import type { Board } from "./types.ts";
import { readRefreshInterval, REFRESH_INTERVAL_MS, shouldStartVisitRefresh } from "./visit.ts";

export const boardState = $state({
	board: null as Board | null,
	refreshing: false,
});

let inflightGet: Promise<Board> | null = null;
let inflightRefresh: Promise<Board> | null = null;
let lastVisitRefreshAt = 0;

export async function loadBoard(kind: "get" | "refresh", opts?: { silent?: boolean }): Promise<Board> {
	if (kind === "get") {
		if (boardState.board) return boardState.board;
		if (inflightGet) return inflightGet;
	}
	if (kind === "refresh") {
		if (inflightRefresh) {
			if (!opts?.silent) boardState.refreshing = true;
			return inflightRefresh;
		}
		if (!opts?.silent) boardState.refreshing = true;
	}
	const run = (async () => {
		try {
			boardState.board =
				kind === "refresh"
					? await postJson<Board>("/api/providers/refresh", {})
					: await getJson<Board>("/api/providers");
			if (kind === "refresh") lastVisitRefreshAt = Date.now();
			return boardState.board;
		} finally {
			if (kind === "refresh") {
				boardState.refreshing = false;
				inflightRefresh = null;
			}
			if (kind === "get") inflightGet = null;
		}
	})();
	if (kind === "get") inflightGet = run;
	if (kind === "refresh") inflightRefresh = run;
	return run;
}

/** Provider verdict for spending a usage-limit reset. */
export type ResetOutcome = {
	provider: string;
	result: "reset" | "already_used" | "not_limited" | "cooldown" | "ineligible" | "unavailable" | "error";
};

/**
 * Spend one usage-limit reset. The server shells out to the provider CLI, so
 * this is the account's real redemption; callers must confirm first. Only a
 * landed reset refreshes the board (spent ticket, cleared windows).
 */
export async function resetProvider(id: string): Promise<ResetOutcome> {
	const outcome = await postJson<ResetOutcome>(`/api/providers/${id}/reset`, {});
	if (outcome.result === "reset") {
		await loadBoard("refresh").catch(() => boardState.board);
	} else if (outcome.result === "already_used" || outcome.result === "ineligible") {
		// The server closed the ticket in its history; the card drops it.
		boardState.board = await getJson<Board>("/api/providers").catch(() => boardState.board);
	}
	return outcome;
}

/** Settings toggle: spend a reset ticket in its last five minutes. */
export async function setAutoReset(enabled: boolean): Promise<void> {
	const { autoReset } = await postJson<{ autoReset: boolean }>("/api/providers/auto-reset", { enabled });
	if (boardState.board) boardState.board.autoReset = autoReset;
}

/**
 * Save the card order the user dragged to. The board reorders at once so the
 * cards do not snap back while the request is out; a failure reloads the
 * server's order before the error reaches the caller.
 */
export async function saveProviderOrder(order: string[]): Promise<void> {
	const board = boardState.board;
	if (board) {
		const rank = (id: string) => {
			const index = order.indexOf(id);
			return index < 0 ? order.length : index;
		};
		board.providers.sort((a, b) => rank(a.id) - rank(b.id));
		board.order = order;
	}
	try {
		boardState.board = await postJson<Board>("/api/providers/order", { order });
	} catch (error) {
		boardState.board = await getJson<Board>("/api/providers").catch(() => boardState.board);
		throw error;
	}
}

export async function visitBoard(now = Date.now()): Promise<Board> {
	try {
		await loadBoard("get");
	} catch {
		// live refresh still runs
	}
	const intervalMs = REFRESH_INTERVAL_MS[readRefreshInterval()];
	if (!shouldStartVisitRefresh(now, lastVisitRefreshAt, inflightRefresh !== null, intervalMs)) {
		if (inflightRefresh) return inflightRefresh;
		if (boardState.board) return boardState.board;
	}
	return loadBoard("refresh");
}

